  '检查磁盘、两个库、FFmpeg、密钥和模型配置；诊断包里的密钥、网址参数、邮箱和手机号都已遮去，不含任何项目内容。': 'Kiểm tra ổ đĩa, hai kho dữ liệu, FFmpeg, khóa và cấu hình mô hình. Khóa, tham số địa chỉ, email và số điện thoại trong gói chẩn đoán đều đã được che, và gói không chứa nội dung dự án nào.',
  '每一章调用一次文本模型（按用量计费），找出角色、场景和道具放进待确认清单；确认后才放进资产库。': 'Mỗi chương gọi mô hình văn bản một lần (tính phí theo mức dùng) để tìm nhân vật, bối cảnh và đạo cụ vào danh sách chờ xác nhận; chỉ khi xác nhận mới vào thư viện tài sản.',
  '每个环节开头的创作方法可以跟随平台、追加你的几条，或换成你自己的；资料、本片事实和输出格式始终由平台给出，不受这里影响。只对你自己的项目生效。': 'Phương pháp sáng tác mở đầu mỗi khâu có thể theo nền tảng, thêm vài dòng của bạn, hoặc thay bằng cách của riêng bạn. Tài liệu, dữ kiện của phim và định dạng đầu ra luôn do nền tảng cung cấp và không bị ảnh hưởng ở đây. Chỉ áp dụng cho dự án của chính bạn.',
  '由模型给出，仅供参考；不代表已经执行了什么，也不是授权。': 'Do mô hình đưa ra, chỉ để tham khảo; không có nghĩa là đã thực hiện gì, cũng không phải là sự cho phép.',
