  '本镜还没有导演台参考。打开导演台摆好站位与机位，截一张静帧或导出一段白模视频，再「应用至分镜」。': 'Cảnh quay này chưa có tham chiếu từ bàn đạo diễn. Mở bàn đạo diễn, bố trí vị trí diễn và máy quay, chụp một khung tĩnh hoặc xuất một video mô hình trắng, rồi bấm “Áp dụng vào phân cảnh”.',
