  '详细剧本后台撰写已中断': "Viết kịch bản chi tiết ở chế độ nền đã bị gián đoạn",
  '已写完 {written}/{total} 集，全部写完后一次性显示。角色设计可以先开始，分镜会等剧本写完。': "Đã viết {written}/{total} tập. Kịch bản hiện ra khi viết xong tất cả các tập. Có thể bắt đầu thiết kế nhân vật ngay; phân cảnh sẽ chờ kịch bản xong.",
  '已写完 {written}/{total} 集并已保留。点「补写」从缺的那一集接着写。': "Đã viết và giữ lại {written}/{total} tập. Bấm \"Viết bổ sung\" để viết tiếp từ tập còn thiếu.",
