  '给这个人的每种情绪写一套自己的样子。镜头读到这个人这一镜的情绪时，用的是这一条，而不是通用写法。': 'Mỗi cảm xúc của nhân vật có một dáng vẻ riêng. Khi cảnh quay đọc được cảm xúc đó, sẽ dùng cách này thay cho cách viết chung.',
