  '已登记 {0} 个火山方舟真人素材，Seedance 视频用它们。': 'Đã đăng ký {0} tư liệu người thật trên Volcengine Ark; video Seedance dùng chúng.',
  '还没登记火山方舟真人素材：Seedance 不收直接上传的真人照片，这名演员的镜头在 Seedance 上只能按文字描述。': 'Chưa đăng ký tư liệu người thật trên Volcengine Ark: Seedance không nhận ảnh người thật tải lên, nên trên Seedance diễn viên này chỉ được mô tả bằng chữ.',
  '还缺正脸特写：请在「正脸特写」槽位上传本人正脸照片。': 'Thiếu ảnh cận mặt: hãy tải ảnh chính diện của người này vào ô cận mặt.',
  '修改': 'Sửa',
  '取消真人演员': 'Bỏ diễn viên thật',
  '有演员本人的照片？设为真人演员后，分镜和视频按本人照片生成，尽量像本人。': 'Có ảnh của chính diễn viên? Đặt làm diễn viên thật để phân cảnh và video bám sát ảnh nhất có thể.',
  '设为真人演员': 'Đặt làm diễn viên thật',
  '先在本演员的「正脸特写」槽位上传本人正脸照片(必需)，「正面全身」上传全身照(建议)。': 'Trước tiên tải ảnh chính diện vào ô cận mặt (bắt buộc) và ảnh toàn thân vào ô toàn thân chính diện (khuyên dùng).',
  '照片上是谁': 'Người trong ảnh',
