  '如：《暗室回声》短剧拍摄与宣发': 'vd: quay và quảng bá phim ngắn 暗室回声',
  '授权到': 'Được ủy quyền đến',
  '火山方舟真人素材 ID（每行一个）': 'ID tư liệu người thật Volcengine Ark (mỗi dòng một)',
  'Seedance 视频只接受演员本人在火山方舟「真人人像库」完成真人认证后入库的素材；入库后把素材 ID 填在这里。': 'Seedance chỉ nhận tư liệu mà chính diễn viên đưa vào thư viện người thật của Volcengine Ark sau khi xác minh; nhập ID tư liệu ở đây.',
  '素材 ID 应是 asset://asset-… 的形式：{0}': 'ID tư liệu có dạng asset://asset-…: {0}',
  '我确认已取得照片中本人对上述用途的肖像使用授权': 'Tôi xác nhận người trong ảnh đã cho phép dùng chân dung cho mục đích trên',
  '已把“{0}”设为真人演员，分镜和视频按本人照片生成。': '“{0}” giờ là diễn viên thật; phân cảnh và video theo ảnh của họ.',
  '已取消“{0}”的真人演员设置。': '“{0}” không còn là diễn viên thật.',
