  '像本人 {0}': 'Giống {0}',
  '不像本人 {0}': 'Không giống {0}',
  '重跑分镜阶段只补画未完成或已退回的场次，已完成的分镜页会保留；但第 5 阶段及之后已生成的视频、音频与成片会被清除（逐集制作时只清当前集）。继续吗？': 'Chạy lại giai đoạn phân cảnh chỉ vẽ bù các cảnh chưa xong hoặc bị trả lại; các trang phân cảnh đã xong được giữ nguyên. Nhưng video, âm thanh và bản dựng đã tạo từ giai đoạn 5 trở đi sẽ bị xóa (khi làm theo từng tập thì chỉ xóa của tập hiện tại). Tiếp tục chứ?',
  '“{0}”的{1}已删除，但主参考图里还留着同一张，没删掉。请再删一次主参考图。': 'Đã xóa {1} của “{0}”, nhưng ảnh tham chiếu chính vẫn còn giữ đúng ảnh đó và chưa xóa được. Hãy xóa ảnh tham chiếu chính thêm một lần nữa.',
  '主参考图': 'Ảnh tham chiếu chính',
  '重跑分镜阶段只补画未完成或已退回的场次，已完成的分镜页会保留；但第 {0} 集已生成的视频、音频与剪辑会被清除，其他各集的视频和成片都保留。继续吗？': 'Chạy lại giai đoạn phân cảnh chỉ vẽ bù các cảnh chưa xong hoặc bị trả lại; các trang phân cảnh đã xong được giữ nguyên. Nhưng video, âm thanh và bản dựng đã tạo của tập {0} sẽ bị xóa; video và bản phim hoàn chỉnh của các tập khác được giữ lại. Tiếp tục chứ?',
  '重跑分镜阶段只补画未完成或已退回的场次，已完成的分镜页会保留；各集成片都保留，但已生成的宣发内容会被清除。继续吗？': 'Chạy lại giai đoạn phân cảnh chỉ vẽ bù các cảnh chưa xong hoặc bị trả lại; các trang phân cảnh đã xong được giữ nguyên. Bản phim hoàn chỉnh của từng tập được giữ lại, nhưng nội dung quảng bá đã tạo sẽ bị xóa. Tiếp tục chứ?',
