  '已同步：铺了 {0} 个镜头，更新 {1} 个节点，保留画布上的 {2} 处': 'Đã đồng bộ: trải {0} cảnh quay, cập nhật {1} nút, giữ {2} chỗ của bảng vẽ',
  '把项目分镜的变化带到画布上：补上还没有的镜头，带过来项目里改了、画布上没动过的内容。画布上改过的不会被覆盖，节点不会被移动或删除。': 'Mang các thay đổi của storyboard dự án vào bảng vẽ: thêm các cảnh quay còn thiếu và cập nhật những gì dự án đã đổi ở chỗ bảng vẽ chưa sửa. Không ghi đè những gì đã sửa trên bảng vẽ, không di chuyển hay xóa nút nào.',
  '新镜头': 'Cảnh quay mới',
  '没有需要改的。': 'Không có gì cần đổi.',
