  '画布上': 'Trên bảng vẽ',
  '画布上也改过，或者这个节点是有同步之前铺的，看不出是哪边改的。默认保留画布上的；勾选的改用项目里的。': 'Hoặc bảng vẽ cũng đã sửa, hoặc nút này được trải ra trước khi có đồng bộ, nên không rõ bên nào đã đổi. Mặc định giữ bản trên bảng vẽ; mục được đánh dấu sẽ dùng bản của dự án.',
