  '画布和它用到的本服务器媒体文件打成一个包，可以导入到别的项目或服务器。元素库的私有图片不打包，外站链接原样保留。': 'Canvas cùng các tệp phương tiện nó dùng trên máy chủ này được đóng thành một gói, có thể nhập vào dự án hoặc máy chủ khác. Ảnh riêng tư của thư viện phần tử không được đóng gói; liên kết tới trang khác được giữ nguyên.',
