  '已保存，之后运行的节点用新模型。': 'Đã lưu. Các nút chạy từ giờ sẽ dùng mô hình mới.',
  '成片镜头': 'Các cảnh quay trong phim',
  '把镜头按顺序接到一个「成片」节点上，和还没生成的首帧、视频、配音一起运行。搭节点不花钱，运行前照常报价、由你确认。': 'Nối các cảnh quay theo thứ tự vào một nút «Thành phim» và chạy cùng các khung đầu, video, lồng tiếng còn thiếu. Dựng nút không tốn phí; trước khi chạy vẫn báo giá và chờ bạn xác nhận như thường lệ.',
