  '搭建成片失败': 'Không dựng được phim',
  '有台词但没声音的镜头配上配音（按项目角色分声）': 'Lồng tiếng cho các cảnh có lời thoại nhưng không có tiếng (mỗi nhân vật một giọng)',
  '模型配置中心还没有启用这一类模型': 'trung tâm mô hình chưa bật mô hình loại này',
  '模型配置中心默认（{0}）': 'Mặc định của trung tâm mô hình ({0})',
  '每个镜头一对节点：首帧 → 视频，带上时长和台词': 'Mỗi cảnh quay một cặp nút: khung đầu → video, kèm thời lượng và lời thoại',
  '流水线正在执行某一步，等它结束再换模型。': 'Quy trình đang chạy một bước; hãy đổi mô hình khi bước đó xong.',
  '清点镜头…': 'Đang kiểm đếm cảnh quay…',
  '视频节点和流水线的视频阶段': 'Các nút video và bước video của quy trình',
  '读取成片内容失败': 'Không đọc được nội dung phim',
  '读取模型设置失败': 'Không đọc được cài đặt mô hình',
  '还要生成：首帧 {0} 个、视频 {1} 个、配音 {2} 条、配乐 {3} 条，最后合成成片。': 'Còn phải tạo: {0} khung đầu, {1} video, {2} đoạn lồng tiếng, {3} bản nhạc, sau đó ghép thành phim.',
  '这些镜头用的视频模型自己会出声，不另外配音；出来没声音的，再点一次一键成片就会补上配音。': 'Mô hình video của các cảnh này tự tạo âm thanh nên không lồng tiếng thêm; nếu video ra không có tiếng, bấm tạo phim lần nữa sẽ được bổ sung lồng tiếng.',
  '这是项目自己的模型设置：流水线各阶段和画布上没有单独选模型的节点都用它。只能选模型配置中心启用了的模型。': 'Đây là mô hình của chính dự án: các bước của quy trình và mọi nút trên bảng vẽ chưa chọn mô hình riêng đều dùng chúng. Chỉ chọn được mô hình đã bật trong trung tâm mô hình.',
  '配乐和音效要用 ElevenLabs，模型配置中心还没有可用的密钥；一键成片可以先不加配乐。': 'Nhạc nền và hiệu ứng cần ElevenLabs, trung tâm mô hình chưa có khóa dùng được; có thể tạo phim trước mà không có nhạc nền.',
  '配乐和音效：ElevenLabs 可用。': 'Nhạc nền và hiệu ứng: có thể dùng ElevenLabs.',
  '配乐要求': 'Yêu cầu nhạc nền',
  '配乐要求（留空用默认）': 'Yêu cầu nhạc nền (để trống dùng mặc định)',
  '配音节点、一键成片的配音和流水线的配音': 'Nút lồng tiếng, lồng tiếng của phim một chạm và của quy trình',
