  '{0}（未启用，实际用 {1}）': '{0} (chưa bật; dùng {1} thay thế)',
  '视频会作为这些镜头的参考视频；已经出过片的镜头，还会在镜头工作台里多一个可「选用此版」的版本。': 'Video sẽ làm video tham chiếu cho các cảnh quay này; cảnh quay đã có clip còn có thêm một phiên bản để bấm "Dùng phiên bản này" trong bàn làm việc cảnh quay.',
  '做法': 'Cách làm',
  '无痕擦除（去字幕、去水印）': 'Xóa liền mạch (phụ đề, hình mờ)',
  '隐私模糊': 'Làm mờ riêng tư',
  '马赛克': 'Khảm (mosaic)',
  '选区': 'Vùng',
  '按下面的数字': 'Theo các số bên dưới',
  '底部字幕条（整行）': 'Dải phụ đề dưới (cả hàng)',
  '顶部字幕条（整行）': 'Dải phụ đề trên (cả hàng)',
  '无痕擦除用周围像素补上固定位置的字幕、台标或水印；隐私打码用模糊或马赛克；会移动的东西擦不掉': 'Xóa liền mạch lấp phụ đề, logo hoặc hình mờ cố định bằng điểm ảnh xung quanh; che riêng tư dùng làm mờ hoặc khảm; vật chuyển động không xóa được',
  '要的是 {0} 个镜头，模型给了 {1} 个：可以重新运行，或铺上去后删掉多的': 'Yêu cầu {0} cảnh quay, mô hình trả về {1}: chạy lại, hoặc trải ra rồi xóa bớt',
  '镜头数（0 = 按剧本）': 'Số cảnh quay (0 = theo kịch bản)',
  '{0} 改没了': '{0} đã bị mất',
  '写回失败，请稍后再试': 'Ghi lại thất bại, vui lòng thử lại sau',
  '写回改写会归档当前角色、分镜和成片，并从编剧阶段重新开始。旧成果仍保留在版本归档中。是否继续？': 'Ghi lại bản viết lại sẽ lưu trữ nhân vật, phân cảnh và phim hiện tại, rồi bắt đầu lại từ giai đoạn biên kịch. Kết quả cũ vẫn nằm trong kho phiên bản. Tiếp tục?',
  '只改选中的分镜，再核对这次改动会碰到哪些伏笔、约定和后面各集的事；会调用两次文本模型，结果先给你看。': 'Chỉ viết lại các cảnh quay đã chọn, rồi kiểm tra thay đổi chạm đến những chi tiết cài cắm, lời hứa và sự kiện ở các tập sau. Gọi mô hình văn bản hai lần; bạn xem kết quả trước khi lưu.',
  '守住这些再改一次': 'Viết lại lần nữa, giữ những điều này',
