  '这几句台词的顺序和剧本不一致：{0}。可以重新运行，或铺上去后改一下视频节点里的台词': 'Những câu thoại này lệch thứ tự so với kịch bản: {0}. Hãy chạy lại, hoặc trải ra rồi sửa lời thoại trong các nút video',
