  '投稿材料生成失败，请稍后重试。': 'Không chuẩn bị được hồ sơ gửi. Vui lòng thử lại.',
  '按平台「AI剧自制编剧投稿模板」整理的 Word 文档。剧本正文直接按项目剧本排版；男女频、一卡、简介、大纲和人设由文字模型写一次，剧本没改就不再调用。': 'Tài liệu Word theo mẫu gửi kịch bản phim AI của nền tảng. Phần kịch bản được dàn trang trực tiếp từ kịch bản của dự án; đối tượng khán giả, tập thu phí, tóm tắt, dàn ý và nhân vật do mô hình văn bản viết một lần và dùng lại cho đến khi kịch bản thay đổi.',
  '打断制作：正在做的这一步停在下一个节点，已完成的部分保留': 'Ngắt sản xuất: bước đang chạy dừng ở mốc kế tiếp và giữ phần đã xong',
  '从停下的地方接着自动做到成片': 'Tự động làm tiếp từ chỗ đã dừng đến phim hoàn chỉnh',
  '从第一个未完成的步骤开始，每一步做完自动进入下一步': 'Bắt đầu từ bước đầu tiên chưa xong; mỗi bước xong sẽ tự chuyển sang bước tiếp theo',
  '逐步': 'Từng bước',
