  '开端—发展—高潮—回落—结局，高潮放在正中，之后写代价': 'Mở đầu, phát triển, cao trào, thoái trào, kết thúc; cao trào ở giữa, sau đó là cái giá',
  '平凡世界—召唤—跨越门槛—考验—磨难—奖赏—回归': 'Thế giới bình thường, lời gọi, vượt ngưỡng, thử thách, thử thách lớn, phần thưởng, trở về',
  '两三条故事线各走各的，主题互相映照，最后汇合': 'Hai ba tuyến truyện đi song song, phản chiếu nhau rồi hội tụ',
  '两条线在同一集里交替推进，因果咬合，最终相撞': 'Hai tuyến xen kẽ trong cùng một tập, nhân quả móc nối, cuối cùng va chạm',
  '打乱时间顺序讲：倒叙、插叙、闪回，真相逐步拼出': 'Kể không theo thứ tự thời gian: hồi tưởng, chen ngang, sự thật dần ghép lại',
  '结尾回到开头的画面或处境，意义却已经变了': 'Kết thúc quay về hình ảnh hay tình huống mở đầu nhưng ý nghĩa đã khác',
  '每一两集一个独立事件，开头立题、结尾解决，主线贯穿': 'Mỗi một hai tập là một sự việc độc lập, mở rồi giải quyết, có tuyến chính xuyên suốt',
  '规则检查没有读出来，不影响下面的重写': 'Không đọc được kết quả kiểm tra theo quy tắc; phần viết lại bên dưới vẫn dùng được',
  '正在按规则检查这条提示词…': 'Đang kiểm tra prompt này theo quy tắc…',
