  '在纯色背景上生成的片段抠得最干净：背景色要远离人物的衣服、肤色和武器（穿绿色或蓝色衣服、拿银色刀刃的人物，品红通常比蓝、绿好），全身连脚都要在画面里': 'Đoạn tạo trên nền một màu sẽ tách sạch nhất: chọn màu nền khác xa quần áo, màu da và vũ khí (nhân vật mặc xanh lá hoặc xanh dương, cầm lưỡi kiếm bạc thì hồng cánh sen thường tốt hơn xanh), và giữ toàn thân kể cả bàn chân trong khung hình',
