  '连一张剧照：去掉人物、道具等叙事元素，重建这个地点平常的样子，机位和透视不变': 'Nối một ảnh phim: nhân vật, đạo cụ và các yếu tố kể chuyện khác được bỏ đi, địa điểm được dựng lại như lúc bình thường, giữ nguyên vị trí máy và phối cảnh',
  '连一张剧照，得到一条从暗到亮的纯色色块；再连一张自己的配色条，它的颜色也会算进去': 'Nối một ảnh phim để có một dải ô màu phẳng từ tối đến sáng; nối thêm dải màu của riêng bạn thì màu của nó cũng được tính vào',
  '连三张图：空间基底、原始剧照、配色卡。空间照基底，光影照原图，配色照色卡': 'Nối ba ảnh: nền không gian, ảnh phim gốc và thẻ màu. Không gian theo nền, ánh sáng theo ảnh gốc, màu theo thẻ màu',
  '七点式': 'Bảy điểm',
  '钩子—第一转折—升级—中点反转—最大危机—揭露—留钩，短剧常用': 'Móc mở đầu, bước ngoặt đầu, leo thang, đảo chiều giữa chừng, khủng hoảng lớn nhất, hé lộ, móc cuối; thường dùng cho phim ngắn',
  '费希特曲线': 'Đường cong Fichte',
  '一开场就在危机里，危机一个比一个大直到高潮，背景边跑边交代': 'Mở đầu ngay trong khủng hoảng; khủng hoảng sau lớn hơn trước cho đến cao trào, bối cảnh được kể dần trên đường đi',
  '还没想法？给我推荐几个方向': 'Chưa có ý tưởng? Gợi ý vài hướng',
  '不写想法也行：按创作类型和目标观众推荐几个题材不同的方向，挑中的会写进想法框。会用 {0} 调用一次文本模型': 'Có thể để trống ý tưởng: vài hướng thuộc các thể loại khác nhau được gợi ý theo loại sáng tác và khán giả, hướng bạn chọn sẽ được ghi vào ô ý tưởng. Việc này gọi mô hình văn bản {0} một lần',
  '剧本审核': 'Thẩm định kịch bản',
  '把写完的剧本按七个方面审读一遍，出一份带场次和改法的报告。打开不花钱，点了生成才调用文本模型。': 'Đọc kịch bản đã viết xong theo bảy phương diện và lập một báo cáo có số cảnh và cách sửa. Mở ra không tốn phí; chỉ gọi mô hình văn bản khi bạn yêu cầu lập báo cáo.',
  '剧本审核报告': 'Báo cáo thẩm định kịch bản',
  '按故事逻辑、人物逻辑、开场、冲突、反转、情绪、台词七个方面读一遍剧本，每条问题落到具体的场次并给出改法。只是建议，不会改动剧本。': 'Đọc kịch bản theo bảy phương diện: logic câu chuyện, logic nhân vật, mở đầu, xung đột, đảo chiều, cảm xúc và lời thoại. Mỗi vấn đề chỉ vào một cảnh cụ thể và nêu cách sửa. Chỉ là gợi ý, không thay đổi kịch bản.',
  '关闭剧本审核报告': 'Đóng báo cáo thẩm định kịch bản',
  '审核报告没有读出来，请稍后重试。': 'Không đọc được báo cáo thẩm định. Hãy thử lại sau.',
  '审核报告没有生成，请稍后重试。': 'Chưa lập được báo cáo thẩm định. Hãy thử lại sau.',
  '正在读取…': 'Đang đọc…',
  '从剧本直接数出的概况': 'Số liệu đếm trực tiếp từ kịch bản',
  '正在审读剧本…': 'Đang đọc kịch bản…',
