  '剧本在这份报告生成之后改过，下面的结论可能已经对不上，可以重新生成。': 'Kịch bản đã thay đổi sau khi lập báo cáo này, nên các kết luận bên dưới có thể không còn khớp. Bạn có thể lập lại.',
