  '从谷底一步步做起来，把当初的轻视还回去': 'Từ đáy vực từng bước đi lên, trả lại sự khinh thường năm xưa',
  '婆媳、夫妻、亲戚之间的亏欠与清算': 'Nợ nần và thanh toán giữa mẹ chồng nàng dâu, vợ chồng, họ hàng',
  '聪明的孩子把分开的父母重新拉到一起': 'Đứa trẻ thông minh kéo bố mẹ đã chia xa về lại với nhau',
  '一桩案子牵出一串秘密，线索、推理与反转': 'Một vụ án kéo ra cả chuỗi bí mật: manh mối, suy luận và đảo chiều',
  '一个近未来的设定（系统、循环、读心）落在普通人身上': 'Một thiết lập tương lai gần (hệ thống, vòng lặp, đọc tâm) rơi vào người bình thường',
  '灾变来临前回到过去，囤物资、结队、活下去': 'Trở về trước thảm họa: tích trữ, lập đội, sống sót',
  '错位、误会与嘴硬，笑着把事办了': 'Lệch pha, hiểu lầm và cứng miệng; vừa cười vừa xong việc',
