  '美元计价的模型按 1 美元 = ¥{0} 折算': 'Mô hình tính giá bằng đô la được quy đổi theo 1 USD = ¥{0}',
  '官方价按美元计的模型按 1 美元 = ¥{0} 折成人民币。': 'Mô hình có giá chính thức bằng đô la được quy đổi sang nhân dân tệ theo 1 USD = ¥{0}.',
  '人物出场字幕': 'Thẻ tên nhân vật',
  '人物第一次出场时竖排显示姓名和身份，之后不再出现': 'Tên và thân phận hiện dọc khi nhân vật xuất hiện lần đầu, sau đó không hiện nữa',
  '人物第一次出场时，在身旁竖排显示姓名和身份，之后不再出现。位置和时间按分镜排，可以在这里改。': 'Lần đầu nhân vật xuất hiện, tên và thân phận hiện dọc bên cạnh; sau đó không hiện nữa. Vị trí và thời điểm theo phân cảnh, có thể sửa tại đây.',
  '「人物出场字幕」已在基础设定里关掉，成片里不会出现；下面的内容仍会保留。': 'Thẻ tên nhân vật đang tắt trong thiết lập cơ bản nên phim sẽ không hiện; nội dung bên dưới vẫn được giữ.',
  '这一集没有第一次出场的人物。': 'Tập này không có nhân vật nào xuất hiện lần đầu.',
  '分镜里这一侧还站着别人，字幕可能落在别人身旁；看一眼成片，必要时换一侧或换个时间。': 'Phân cảnh có người khác đứng cùng phía nên thẻ có thể nằm cạnh nhầm người; hãy xem phim và đổi phía hoặc thời điểm nếu cần.',
