  '姓名': 'Tên',
  '招式分解图': 'Bảng chiêu thức',
  '招式组': 'Nhóm chiêu',
  '连一张人物图：同一个人按选的一组招式逐格摆出来，图上不出字；把它连到图像或视频节点当动作参考': 'Nối một ảnh nhân vật: cùng một người thể hiện từng chiêu của nhóm đã chọn, mỗi ô một chiêu, không có chữ trên ảnh; nối nó vào nút ảnh hoặc video làm tham chiếu động tác',
  '人物图用全身、手里已经拿着兵器的那张，兵器的长短和样子才不会每格不一样；一个视频节点只挑其中一两格的动作来写，不要把整组塞进一条提示词': 'Dùng ảnh toàn thân đã cầm sẵn vũ khí để độ dài và hình dáng vũ khí giống nhau ở mọi ô; trong một nút video chỉ viết một hai chiêu, đừng nhét cả nhóm vào một lời nhắc',
  '棍法八式': 'Côn, 8 chiêu',
  '长剑八式': 'Kiếm, 8 chiêu',
  '横刀八式': 'Đao, 8 chiêu',
