  '轻功八式': 'Khinh công, 8 chiêu',
  '群战突围五式': 'Phá vòng vây, 5 chiêu',
  '轻功追逐五式': 'Rượt đuổi trên mái, 5 chiêu',
  '长枪破阵五式': 'Thương phá trận, 5 chiêu',
  '弓箭五式': 'Cung tên, 5 chiêu',
